const PHASE7_COMMON_FAQ = {
  question: "Does this answer guarantee a permit or project outcome?",
  answer: "No. The answer provides general engineering orientation. The responsible professional confirms the project scope and evidence, while the authority having jurisdiction controls its requirements, review, interpretation, and approval decision.",
};

function phase7Faqs(page: Phase7AeoSeed): Array<{ question: string; answer: string }> {
  return [
    { question: `What is the short answer about ${page.topic.toLowerCase()}?`, answer: page.answer },
    {
      question: `What does ${page.topic.toLowerCase()} depend on?`,
      answer: `The answer depends on the project scope, governing jurisdiction, current records, design inputs, and the responsible professional's independent review. ${page.answer}`,
    },
    PHASE7_COMMON_FAQ,
    {
      question: "What should I send for an initial engineering review?",
      answer: "Send the project address, plain-language scope, current drawings, existing-condition records, relevant calculations or comments, schedule, and the authority or code information already available. The responsible engineer will identify gaps.",
    },
  ];
}

function assertPhase7Corpus(): void {
  if (PHASE7_AEO_PAGES.length !== 101) {
    throw new Error(`SEO assertion failed: Phase 7 requires exactly 101 new seeds (found ${PHASE7_AEO_PAGES.length})`);
  }
  const existingSlugs = new Set([
    ...PHASE0_AEO_PAGES.map((page) => page.slug),
    ...PHASE0_PLAN_CHECK_PLAYBOOKS.map((page) => page.slug),
    ...PHASE0_RESOURCE_PAGES.map((page) => page.slug),
    ...GUIDE_PAGES.map((page) => page.slug),
  ]);
  const existingHeadings = new Set([
    ...PHASE0_AEO_PAGES.flatMap((page) => [page.title.toLowerCase(), page.h1.toLowerCase()]),
    ...PHASE0_PLAN_CHECK_PLAYBOOKS.flatMap((page) => [page.title, "h1" in page ? page.h1 : undefined].filter((value): value is string => Boolean(value)).map((value) => value.toLowerCase())),
    ...PHASE0_RESOURCE_PAGES.flatMap((page) => [page.title, "h1" in page ? page.h1 : undefined].filter((value): value is string => Boolean(value)).map((value) => value.toLowerCase())),
    ...GUIDE_PAGES.flatMap((page) => [page.title, "h1" in page ? page.h1 : undefined].filter((value): value is string => Boolean(value)).map((value) => value.toLowerCase())),
  ]);
  const slugs = new Set<string>();
  const counts = {} as Record<Phase7Cluster, number>;
  for (const page of PHASE7_AEO_PAGES) {
    if (slugs.has(page.slug) || existingSlugs.has(page.slug)
      || existingHeadings.has(page.title.toLowerCase()) || existingHeadings.has(page.h1.toLowerCase())) {
      throw new Error(`SEO assertion failed: Phase 7 slug overlaps an existing corpus route: ${page.slug}`);
    }
    slugs.add(page.slug);
    counts[page.cluster] = (counts[page.cluster] ?? 0) + 1;
    if (!/^\/(?:services|permit-engineering|pe-stamp|[a-z0-9-]+\/)/.test(page.serviceHref)
      || !page.answer.trim() || page.answer.length < 120
      || !/^[a-z0-9-]+$/.test(page.slug)) {
      throw new Error(`SEO assertion failed: incomplete Phase 7 seed: ${page.slug}`);
    }
  }
  for (const cluster of Object.keys(PHASE7_CLUSTER_COUNTS) as Phase7Cluster[]) {
    if (counts[cluster] !== PHASE7_CLUSTER_COUNTS[cluster]) {
      throw new Error(`SEO assertion failed: Phase 7 ${cluster} count is ${counts[cluster] ?? 0}, expected ${PHASE7_CLUSTER_COUNTS[cluster]}`);
    }
  }
  const reportDir = path.join(__dirname, "reports");
  fs.mkdirSync(reportDir, { recursive: true });
  fs.writeFileSync(path.join(reportDir, "phase7-corpus.json"), `${JSON.stringify({
    generatedAt: "deterministic",
    existingAnswerPages: PHASE0_AEO_PAGES.length,
    phase7SeedPages: PHASE7_AEO_PAGES.length,
    answerLibraryPages: PHASE0_AEO_PAGES.length + PHASE7_AEO_PAGES.length,
    clusterCounts: PHASE7_CLUSTER_COUNTS,
  }, null, 2)}\n`);
}

/** Placeholder-FAQ guard (2026-11-03): some AEO records carry literal scaffold
 * pairs ({ question: "question", answer: "answer" }) in their faqs data. Those
 * pairs are not content and must never render visibly or into the FAQPage
 * schema. The rule is deliberately narrow: it drops only the literal
 * placeholder pair (and empty pairs); it never judges substantive content. */
function substantiveFaqs(faqs: Array<{ question: string; answer: string }>): Array<{ question: string; answer: string }> {
  return faqs.filter((faq) => {
    const q = faq.question.trim().toLowerCase();
    const a = faq.answer.trim().toLowerCase();
    return q !== "" && a !== "" && !(q === "question" && a === "answer");
  });
}

function phase0FaqSchema(faqs: Array<{ question: string; answer: string }>) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((faq) => ({
      "@type": "Question",
      name: faq.question,
      acceptedAnswer: { "@type": "Answer", text: faq.answer },
    })),
  };
}

function phase0FaqMarkup(faqs: Array<{ question: string; answer: string }>): string {
  return `<section class="block"><div class="container"><h2>Frequently Asked Questions</h2><div class="faq">
    ${faqs.map((faq) => `<details><summary>${esc(faq.question)}</summary><div class="a">${esc(faq.answer)}</div></details>`).join("")}
  </div></div></section>`;
}

/** Apex residuals (2026-10-19): section-style FAQ block for the solutions /
 * discipline / structural-extended families. The visible markup and the
 * FAQPage schema (residualsFaqSchemaList) are both built from the same
 * data array, so visible/schema parity holds by construction. */
function residualsFaqSection(faqs?: Array<{ question: string; answer: string }>): string {
  return faqs?.length ? `
    <section class="section section--white faq">
      <div class="container container--narrow">
        <h2>Frequently Asked Questions</h2>
        ${faqs.map((f) => `<details><summary>${esc(f.question)}</summary><div class="a">${esc(f.answer)}</div></details>`).join("\n        ")}
      </div>
    </section>` : "";
}

function residualsFaqSchemaList(faqs?: Array<{ question: string; answer: string }>): unknown[] {
  return faqs?.length ? [phase0FaqSchema(faqs)] : [];
}

function assertPhase0Page(html: string, canonical: string, faqs: Array<{ question: string; answer: string }>, label: string): void {
  const schemas = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)]
    .map((match) => JSON.parse(match[1]) as { "@type"?: string; mainEntity?: unknown[] });
  if ((!html.includes('data-phase0="true"') && !html.includes('data-phase7="true"'))
    || (html.match(/<h1(?:\s[^>]*)?>/gi) ?? []).length !== 1
    || !html.includes(`<link rel="canonical" href="${SITE}${canonical}"`)
    || html.includes('name="robots" content="noindex')
    || !html.includes("By ")
    || html.includes("Apex Grid Engineering PE Team")
    || !html.includes(`Updated ${PHASE0_UPDATED_DATE}`)
    || (schemas.find((schema) => schema["@type"] === "FAQPage")?.mainEntity?.length ?? 0) !== substantiveFaqs(faqs).length
  ) {
    throw new Error(`SEO assertion failed: malformed Phase 0 page ${label}`);
  }
}


type VisualMotif = "structural" | "mep" | "civil" | "stamping" | "location" | "guide";
const VISUAL_MOTIFS: Record<VisualMotif, { file: string; alt: string }> = {
  structural: { file: "diagram-structural.svg", alt: "Illustrative diagram of a structural load path: roof and floor loads travel through beams and columns down to the foundation footings." },
  mep: { file: "diagram-mep.svg", alt: "Illustrative diagram of building MEP systems: ductwork with diffusers, an electrical panel with conduit, and piping runs." },
  civil: { file: "diagram-civil.svg", alt: "Illustrative diagram of a civil site plan: grading contours around a building pad, a roadway, and storm drainage." },
  stamping: { file: "diagram-stamping.svg", alt: "Illustrative diagram of the professional engineer review and seal workflow: drawings are reviewed against a checklist, sealed by a licensed PE, and issued as a permit set." },
  location: { file: "diagram-location.svg", alt: "Illustrative map diagram marking an Apex Grid Engineering service location with a map pin over a street grid." },
  guide: { file: "diagram-guide.svg", alt: "Illustrative engineering blueprint diagram with dimension lines, a framing elevation sketch, and a title block." },
};
function familyVisual(motif: VisualMotif, altSuffix?: string): string {
  const m = VISUAL_MOTIFS[motif];
  const alt = altSuffix ? `${m.alt} ${altSuffix}` : m.alt;
  return `<figure class="family-visual"><img src="/images/diagrams/${m.file}" alt="${esc(alt)}" width="1200" height="520" loading="lazy" decoding="async"></figure>`;
}
function motifForText(text: string): VisualMotif {
  const t = text.toLowerCase();
  if (/(stamp|seal|plan check|permit set|pe review)/.test(t)) return "stamping";
  if (/(beam|column|foundation|footing|framing|load path|seismic|retaining wall|truss|joist|structural|concrete|masonry|shear wall|moment frame|lintel|slab|pier|grade beam|steel design|wood design)/.test(t)) return "structural";
  if (/(hvac|duct|electrical|panel|plumbing|piping|mechanical|lighting|conduit|fire protection|fire sprinkler|\bmep\b|energy code|title 24|comcheck|generator|switchgear|transformer|boiler|chiller|air handler|exhaust|ventilation|water heater|gas line|load calculation)/.test(t)) return "mep";
  if (/(grading|drainage|stormwater|site plan|civil site|paving|sidewalk|retention pond|detention|erosion|topograph|subdivision|driveway|parking lot|septic|culvert)/.test(t)) return "civil";
  return "guide";
}
function motifForDiscipline(slug: string): VisualMotif {
  if (slug.startsWith("structural")) return "structural";
  if (slug.startsWith("civil") || slug.startsWith("geotechnical")) return "civil";
  if (slug.startsWith("mep") || slug.startsWith("mechanical") || slug.startsWith("electrical") || slug.startsWith("plumbing")) return "mep";
  return "guide";
}

function phase0ArticleFrame(
  opts: {
    canonical: string;
    title: string;
    description: string;
    h1: string;
    kicker: string;
    answer: string;
    sections: Array<{ heading: string; body: string; bullets?: string[]; bulletsHtml?: string[] }>;
    faqs: Array<{ question: string; answer: string }>;
    links?: Array<{ label: string; href: string }>;
    schemaType?: "Article" | "Service" | "WebPage";
    author?: string;
    founderNote?: string;
    marker?: string;
    directAnswer?: string;
    suppressEmptyFaq?: boolean;
    facts?: Array<{ label: string; value: string }>;
    howTo?: boolean;
    visual?: VisualMotif;
    extraBodyHtml?: string;
  },
): string {
  const crumbs = [{ name: "Home", href: "/" }, { name: opts.h1 }];
  const author = opts.author ?? PHASE0_EDITORIAL_AUTHOR;
  const byline = `By ${esc(author)}${author === PHASE0_JEREMY_AUTHOR ? "." : ""}`;
  const authorSchema = author === PHASE0_JEREMY_AUTHOR
    ? {
      "@type": "Person",
      name: "Jeremy Mills",
      jobTitle: "CEO & Founder",
      description: "USAF Veteran",
      worksFor: { "@type": "Organization", name: "Apex Grid Engineering", url: SITE },
    }
    : { "@type": "Organization", name: PHASE0_EDITORIAL_AUTHOR, url: SITE };
  const schema = {
    "@context": "https://schema.org",
    "@type": opts.schemaType ?? "Article",
    headline: opts.h1,
    name: opts.h1,
    description: opts.description,
    url: `${SITE}${opts.canonical}`,
    datePublished: PHASE0_UPDATED_DATE,
    dateModified: PHASE0_UPDATED_DATE,
    author: authorSchema,
    publisher: { "@type": "Organization", name: "Apex Grid Engineering", url: SITE },
  };
  // Lede de-duplication guard: a body section that repeats the hero text
  // (direct answer or lede) verbatim is dropped, so the opening paragraph
  // is never reproduced as the first body section.
  const heroText = opts.directAnswer ?? opts.answer;
  const sections = opts.sections.filter((section) => section.body.trim() !== heroText.trim());
  const howToSchema = opts.howTo ? {
    "@context": "https://schema.org",
    "@type": "HowTo",
    name: opts.h1,
    description: opts.directAnswer ?? opts.answer,
    step: sections.map((section, index) => ({
      "@type": "HowToStep",
      position: index + 1,
      name: section.heading,
      text: section.body,
      url: `${SITE}${opts.canonical}#step-${index + 1}`,
    })),
  } : undefined;
  const hero = opts.directAnswer
    ? `<section class="hero"><div class="container"><p class="kicker">${esc(opts.kicker)}</p><h1>${esc(opts.h1)}</h1>
      <p class="note">${byline} · Updated ${PHASE0_UPDATED_DATE}</p>
      <div class="direct-answer" aria-label="Direct answer"><p>${esc(opts.directAnswer)}</p></div>
      ${opts.founderNote ? `<p class="founder-note">${esc(opts.founderNote)}</p>` : ""}
    </div></section>`
    : `<section class="hero"><div class="container"><p class="kicker">${esc(opts.kicker)}</p><h1>${esc(opts.h1)}</h1><p class="lede">${esc(opts.answer)}</p>
      <p class="note">${byline} · Updated ${PHASE0_UPDATED_DATE}</p>${opts.founderNote ? `<p class="founder-note">${esc(opts.founderNote)}</p>` : ""}
    </div></section>`;
  const body = `<main ${opts.marker ? `data-${opts.marker}="true"` : 'data-phase0="true"'}>
  ${breadcrumb(crumbs)}
  ${hero}
  ${opts.visual ? familyVisual(opts.visual) : ""}
  ${opts.extraBodyHtml ?? ""}
  ${opts.facts?.length ? `<section class="block"><div class="container"><h2>What facts should you use to plan this scope?</h2><div class="prose"><table><thead><tr><th>Planning fact</th><th>Project-specific value</th></tr></thead><tbody>${opts.facts.map((fact) => `<tr><th scope="row">${esc(fact.label)}</th><td>${esc(fact.value)}</td></tr>`).join("")}</tbody></table></div></div></section>` : ""}
  ${sections.map((section, index) => `<section class="block" id="step-${index + 1}"><div class="container"><h2>${esc(section.heading)}</h2><div class="prose"><p>${esc(section.body)}</p>${section.bulletsHtml ? `<ul class="scope">${section.bulletsHtml.map((bullet) => `<li>${bullet}</li>`).join("")}</ul>` : section.bullets ? `<ul class="scope">${section.bullets.map((bullet) => `<li>${esc(bullet)}</li>`).join("")}</ul>` : ""}</div></div></section>`).join("")}
  ${opts.links?.length ? `<section class="block"><div class="container"><h2>${opts.directAnswer ? "Which related engineering resources can help?" : "Related Engineering Resources"}</h2><div class="linkrow">${opts.links.map((link) => `<a href="${esc(link.href)}"${/^https:\/\//.test(link.href) ? ' rel="noopener noreferrer"' : ""}>${esc(link.label)}</a>`).join("")}</div></div></section>` : ""}
  ${opts.suppressEmptyFaq && opts.faqs.length === 0 ? "" : opts.directAnswer ? `<section class="block"><div class="container"><h2>What else do project teams ask?</h2><div class="faq">${opts.faqs.map((faq) => `<details><summary>${esc(faq.question)}</summary><div class="a">${esc(faq.answer)}</div></details>`).join("")}</div></div></section>` : phase0FaqMarkup(opts.faqs)}
  <section class="ctaband"><div class="container"><h2>${opts.directAnswer ? "Ready to discuss your engineering scope?" : "Discuss your engineering scope"}</h2><p>Share the project address, current records, requested deliverable, authority information, and schedule. Apex Grid confirms professional responsibility, availability, and scope before work begins.</p><a class="cta" href="/contact">Request a Project Review</a></div></section>
  </main>`;
  return htmlShell({
    title: opts.title,
    description: opts.description,
    canonical: `${SITE}${opts.canonical}`,
    schemaJson: [schema, ...(opts.suppressEmptyFaq && opts.faqs.length === 0 ? [] : [phase0FaqSchema(opts.faqs)]), ...(howToSchema ? [howToSchema] : []), breadcrumbSchema(crumbs)],
    body,
    // Phone-format cure (2026-11-01): money families rendered through this
    // frame carry the hyphenated phone in the footer contact block.
    money:
      opts.canonical.startsWith("/answers/") ||
      opts.canonical.startsWith("/pe-stamp/") ||
      opts.canonical.startsWith("/resources/"),
  });
}

// Rank-recovery strike 2026-10-30 (fuel-tank cure): additive in-content link
// support INTO /answers/airport-fuel-storage-facility-design/ from its closest
// sibling answers. Keyed by answer slug; every other answers page passes
// undefined and renders byte-identical output.
const ANSWER_EXTRA_SECTIONS: Record<string, string> = {
  "student-housing-structural": `<section class="block"><div class="container"><h2>Who Designs the <em>Structure</em></h2><div class="prose"><p>The costs above are set by the structural system — podium, timber frame, and the amenity stack — long before finishes are discussed. The engineering behind those decisions is covered in this firm's guide to <a href="/industries/multifamily/student-housing/structural-engineering/">student housing structural engineer</a> services: podium transfer design, wood-over-concrete framing, and the schedule discipline a leased-up opening date demands.</p></div></div></section>`,
  "cleanroom-mep-engineering-requirements": `<section class="block"><div class="container"><h2>From requirements to a <em>stamped design</em></h2><div class="prose"><p>The requirements on this page — classification, air changes, pressurization, filtration — become a permit-ready set through <a href="/industries/life-science/cleanroom-mep-engineering/">cleanroom MEP engineering</a>: the dedicated scope where Apex Grid designs ISO 5 through ISO 8 cleanroom mechanical and electrical systems and documents them for certification and validation.</p></div></div></section>`,
  "airport-fuel-farm-design": `<section class="block"><div class="container"><h2>The storage facility behind the <em>fuel farm</em></h2><div class="prose"><p>The fuel farm tanks sit inside a storage facility engineered as its own scope — tank foundations and anchorage, secondary containment, leak detection, hazardous-location electrical, fire protection, and piping, with fire code, environmental regulations, and airport standards reconciled into one buildable facility. That facility-level scope is covered in our guide to <a href="/answers/airport-fuel-storage-facility-design/">airport fuel storage facility design</a>.</p></div></div></section>`,
  "industrial-fuel-storage-design": `<section class="block"><div class="container"><h2>Fuel storage at the <em>airport</em></h2><div class="prose"><p>Aviation fuel storage runs the same containment-first discipline — tank selection and sizing, secondary containment, leak detection, and fire protection — under an added overlay of airport standards, with the tank farm tied into hydrant and truck distribution. See how the scopes compare in our guide to <a href="/answers/airport-fuel-storage-facility-design/">aviation fuel tank design</a> for airport facilities.</p></div></div></section>`,
  "tank-farm-design": `<section class="block"><div class="container"><h2>Tank farms for <em>aviation fuel</em></h2><div class="prose"><p>An airport tank farm applies the same fundamentals — foundations designed for the full fuel load, secondary containment, fire protection, and distribution piping — to aviation fuel, where hazardous-location electrical and airport standards join the design. Our guide to <a href="/answers/airport-fuel-storage-facility-design/">airport fuel storage facility design</a> covers the aviation case in detail.</p></div></div></section>`,
  "drive-thru-restaurant-design": `<section class="block"><div class="container"><h2>Adding a drive-thru window: what changes in the <em>kitchen</em> and on the <em>floor</em></h2><div class="prose"><p>Adding a drive-thru window to an existing quick-service restaurant changes the kitchen layout in one fundamental way: the single order stream splits in two. The kitchen gains a dedicated drive-thru path — a window-side expediter station with its own holding, bagging, and drink points — so window orders are assembled without crossing the counter line, and the staffing model splits with it: at peak, a dedicated order-taker on the headset, a window cashier-expediter, and a runner working the pass replace the shared queue a counter-only crew runs. That is the answer whether the unit is the scenario behind this question — an existing location, a Moe's or any comparable chain restaurant, adding a window it was not built with — or any other quick-service box: two order streams, two assembly paths, and a building altered to keep them from colliding.</p><p><strong>Kitchen layout.</strong> The make-line and pass are reconfigured so both streams can be fed without crossing: window orders get a no-cross-traffic path from the pass to a window-adjacent holding and bagging station, with packaging storage at the window instead of across the kitchen, a point-of-sale and kitchen-display point at the expediter position, and drink and ice capacity duplicated or relocated to the window side. If cooking equipment moves to make room, hood coverage and the fire-suppression envelope are re-verified against the new layout; where the cooking line is untouched, the change is a pass-and-holding alteration, not a kitchen rebuild.</p><p><strong>Staffing and operational flow.</strong> The layout exists to serve a different labor model. A counter-only unit staffs one queue; a drive-thru unit staffs two, and at peak the window side needs its own cashier-expediter and a headset order-taker distinct from the counter cashier, with a runner bridging the shared pass. Off-peak, the roles consolidate back — which is why the window station is designed to be worked by one person at slow hours and three at the rush: reach distances, shelf and holding capacity, and the handoff point at the window are sized for the peak crew and sequenced so a single operator can still run them.</p><p><strong>Equipment and utilities.</strong> The window itself brings a service window unit with an air curtain, a canopy, exterior lighting, and the menu-board and speaker-post circuit outside; inside, it brings added receptacles and small-power loads at the new station, low-voltage runs for the headset system, POS, and kitchen displays, and a panel-schedule check against the added load. None of it is large alone; together it is a real electrical alteration that has to be documented, not improvised.</p><p><strong>Engineering coordination.</strong> The building work is a structural opening cut into an exterior wall — header and lintel design, storefront or masonry rework — plus the site work for the lane: striping, drainage, and a grease-path check so the new lane does not compromise the interceptor or the storm system. The permit set covers the alteration and the site together. The full-building picture behind this alteration is our guide to <a href="/answers/quick-service-restaurant-design/">quick-service restaurant engineering</a>.</p></div></div></section>`,
  "coffee-shop-design": `<section class="block"><div class="container"><h2>Coffee shop engineering: the systems a <em>café</em> actually runs on</h2><div class="prose"><p>Coffee shop engineering is the coordinated design of the systems a café runs on: plumbing that delivers treated water at pressure to the bar and drainage everywhere steam and dishwater land, electrical capacity sized for simultaneous high-draw heating loads in a small footprint, HVAC that clears steam and heat without making the seating area uncomfortable, and the permit set that ties the three together. A coffee shop is a small space carrying commercial-kitchen loads, and the engineering is what makes those loads land in a few hundred square feet of bar and back counter without colliding — that coordination, system by system, is what a new build actually requires.</p><p><strong>Plumbing.</strong> The bar is a plumbing fixture in its own right: espresso machines and brewers need a dedicated water feed with filtration and pressure regulation, drainage at the bar and the dish station, a three-compartment and hand-washing sink arrangement the health reviewer will check, backflow prevention on the supply, and water heating sized for the dish machine's draw. Where the menu adds real food preparation, a grease path joins the list. In a tenant space, the governing question is what the existing building's water and waste services can actually support — answered before the bar layout is fixed, not after.</p><p><strong>Electrical loads.</strong> Espresso machines, grinders, brewers, ovens, and refrigeration all draw at once, and several are continuous or near-continuous loads on dedicated circuits, many at 208–240V. A load calculation against the tenant panel is the first electrical task: cafés regularly land in retail shells whose panels were sized for lighting and receptacles, and the difference between a panel that carries the bar and a service upgrade is decided by that calculation, on paper, before equipment is ordered.</p><p><strong>HVAC and ventilation.</strong> Steam from the dish station and espresso wands, heat from ovens and brewers, and a seating area that has to stay comfortable share one small volume. The mechanical design balances exhaust and makeup air where cooking equipment requires it, keeps the bar's heat and humidity from migrating into the seating, and fits the system into the ceiling space a retail shell actually offers.</p><p><strong>Permitting.</strong> A coffee shop build is permitted as a tenant improvement and reviewed in parallel by the building department and the health authority, and the two reviewers check the same coordinated set from different sides — equipment schedules, plumbing fixtures, and ventilation have to agree across every sheet. The layout and front-of-house side of that set is covered by our <a href="/answers/coffee-shop-design-guide/">coffee shop design guide</a>; this page is the engineering underneath it.</p></div></div></section>`,
  "quick-service-restaurant-design": `<section class="block"><div class="container"><h2>The drive-thru question, answered in <em>depth</em></h2><div class="prose"><p>Most quick-service engineering questions are about the whole building — this page's subject. The most common single alteration is narrower: adding a drive-thru window to a unit that was built without one, which splits the kitchen's order stream in two and reworks its staffing model around the window. That alteration — what changes in kitchen layout, staffing and operational flow, equipment and utilities, and the permit set — is worked through in our answer on <a href="/answers/drive-thru-restaurant-design/">adding a drive-thru window to an existing restaurant</a>.</p></div></div></section>`,
  "coffee-shop-design-guide": `<section class="block"><div class="container"><h2>The engineering set behind the <em>design</em></h2><div class="prose"><p>A design guide settles layout, flow, and finishes; the buildable version of that layout depends on an engineering set sized to it — water and drainage at the bar, panel capacity for the espresso line, and ventilation that clears steam and dish heat from a small footprint. What that set has to contain, system by system, is set out in our answer on <a href="/answers/coffee-shop-design/">the engineering a new coffee shop build needs</a>.</p></div></div></section>`,
  "beachfront-condo-retrofit-engineering": `<section class="block"><div class="container"><h2>Retrofit hurricane protection for <em>condos</em>: the scope, system by system</h2><div class="prose"><p>Retrofit hurricane protection for condos is not a product you bolt on; it is a sequenced scope worked through the existing tower — load path, openings, envelope — and on a beachfront condominium it is set by the condition assessment, not by a catalog. The assessment combines document review, field survey, and testing into the structural condition report the whole retrofit stands on, and in Florida it also satisfies the milestone inspection obligations now imposed on aging coastal condominiums.</p><p><strong>Load path first.</strong> Where the investigation finds inadequate roof-to-wall or wall-to-floor connections, the engineer details supplemental steel straps, angles, and through-bolts, installed from inside or outside with localized demolition. Added shear walls or braced frames go where they stiffen the tower without taking units offline, and balcony slabs with corroded cantilever reinforcement get supplemental supports or carbon-fiber strengthening where the analysis supports it.</p><p><strong>Openings and envelope.</strong> Replacement windows and doors are specified for the calculated component-and-cladding pressures and the impact rating — with anchor pull-testing on the existing substrate, because the best impact window is worthless if its anchors pull out of deteriorated concrete. Balcony waterproofing membranes, railings, and sliding-door tracks are replaced as one system per balcony; a leak at any one element defeats the others.</p><p><strong>Occupied phasing.</strong> The work proceeds stack by stack, every opening weather-protected the same day it is opened and temporary barriers inspected nightly during hurricane season. The phasing plan is an engineering deliverable in its own right — work zones, material staging, crane and hoist locations, and vibration and noise limits set for the residents living under the work.</p></div></div></section>`,
  "hurricane-retrofit-existing-buildings": `<section class="block"><div class="container"><h2>When the existing building is a <em>condominium</em></h2><div class="prose"><p>The retrofit sequence on this page applies to existing buildings generally; a condominium tower adds three complications of its own — association approval and special-assessment funding, unit-by-unit access negotiated with owners, and work phased around residents in place. Those constraints change how the same systems are scoped and sequenced. The condo case is worked through end to end — assessment, load path, opening protection, and the balcony envelope treated as one system — in our answer on <a href=\"/answers/beachfront-condo-retrofit-engineering/\">beachfront condo retrofit engineering</a>.</p></div></div></section>`,
  "florida-hurricane-wind-design-requirements": `<section class="block"><div class="container"><h2>These requirements, applied to an <em>existing condo</em></h2><div class="prose"><p>Florida's wind requirements are written around new design; an existing beachfront condominium meets them through a retrofit — openings and roof connections brought up to the current component-and-cladding pressures and impact ratings, verified against a structure that has already spent decades in salt air. How that scope is assembled for an occupied tower, from the milestone-inspection report forward, is covered in our guide to <a href=\"/answers/beachfront-condo-retrofit-engineering/\">retrofit hurricane protection for condos</a>.</p></div></div></section>`,
  "pe-stamp-only-vs-review-and-seal": `<section class="block"><div class="container"><h2>The check behind the <em>seal</em></h2><div class="prose"><p>Review-and-seal is only worth anything when the engineer behind the seal is licensed in the project's state and in responsible charge of the work — which is why the verification step matters as much as the stamp itself. Owners who want to run that check the way a reviewer would can follow the record field by field: our guide to the <a href=\"/answers/michigan-professional-engineer-license-lookup/\">Michigan professional engineer license lookup</a> works through LARA's system in detail, including how to check the firm behind the individual engineer and what a missing record actually means.</p></div></div></section>`,
  "airport-jet-blast-fence-design": `<section class="block"><div class="container"><h2>The noise question: <em>deadening</em> a jet blast fence</h2><div class="prose"><p>A jet blast fence does two jobs that are easy to confuse. The first is deflection — turning the exhaust stream up and away from people, vehicles, and buildings behind the run-up area. The second is quieter work, literally: a noise deadening jet blast fence is built to absorb and scatter the sound of engines at takeoff power before it reaches the neighborhoods, hangars, and terminal areas beyond the fence line. The two jobs share a structure but not a specification, and a fence engineered only for deflection can leave the noise problem untouched.</p><p>The acoustic version — specified in procurement language variously as a sound-deadening jet blast fence or an acoustical jet blast fence — adds an absorptive build-up to the deflector panel: a perforated metal face sheet on the airfield side, a sound-absorptive core behind it, and a solid back sheet, so engine noise striking the panel is partly absorbed instead of reflected whole at the community. Panel height, length, and placement do the rest of the work: the fence has to interrupt the line of sight between the exhaust source and the receiver, which is why acoustic blast fences are sited with the run-up pad geometry and the nearest noise-sensitive areas in view, not just the blast envelope. None of the acoustic layer is allowed to compromise the first job — the panel and its foundations still take the full jet blast velocity and temperature loads, and louvers, perforations, and joints are detailed so the exhaust stream cannot exploit them.</p><p>Airports ask the noise question because run-up and maintenance areas sit close to the fence line of the community: engine run-ups at full power, often at night, are among the most common sources of airport noise complaints, and federal airport-noise compatibility planning treats that ground noise as part of the airport's footprint. A fence that answers both questions — deflection for safety, absorption for the neighbors — is the complete scope. The structural engineering of the deflector itself, panel framing, foundations, and blast loads, is covered in our companion answer on <a href=\"/answers/jet-blast-deflector-design/\">jet blast deflector design</a>.</p></div></div></section>`,
  "jet-blast-deflector-design": `<section class="block"><div class="container"><h2>When the question is <em>noise</em>, not blast</h2><div class="prose"><p>This page covers the deflector as a structure. Some projects start from the other end: the fence is wanted because run-up noise reaches a neighborhood, a hangar row, or a terminal area, and the deflection is secondary. That scope — absorptive panel construction, siting against the noise receiver, and how the acoustic layer is layered onto a fence that still has to take full blast loads — is a different specification, and it is worked through in our answer on the <a href=\"/answers/airport-jet-blast-fence-design/\">airport jet blast fence</a>, which covers the noise-deadening design in full.</p></div></div></section>`,
  "grain-weigh-scale-design": `<section class="block"><div class="container"><h2>Truck scale integration for <em>grain elevators</em>: the systems around the scale</h2><div class="prose"><p>A weigh scale earns its keep as part of a system, and truck scale integration for grain elevators is the engineering that connects the scale to everything around it: the receiving line it meters, the traffic pattern that keeps loaded and empty trucks from crossing, and the data path that turns each weighing into a settlement ticket. The scale itself — type, capacity, foundation, and approaches — is covered above; the integration layer is what makes it the elevator's metering point rather than a platform trucks happen to cross.</p><p><strong>Traffic and layout.</strong> Integration starts with geometry: separate inbound and outbound lanes where the site allows, a scale length matched to the longest truck-and-trailer combination the facility receives, queuing room that keeps waiting trucks off the public road, and a probe and sampling station positioned so a load is sampled before it is weighed and dumped. The pit, the dump shed, and the scale are laid out as one sequence — probe, weigh, dump, weigh out — and the civil and structural design has to serve that sequence, not fight it.</p><p><strong>Data and controls.</strong> The modern scale house is a data node: digital load cells and a weight indicator tied to the scale-management software that issues tickets, tracks inventory by commodity and bin, and feeds the accounting system; RFID or card readers and intercoms where the facility runs unattended weighing outside office hours; and remote displays positioned so the driver never leaves the cab to read a weight. Specifying that layer means coordinating the scale vendor, the electrician, and the software provider against one set of drawings — conduit, power, and data runs designed with the foundations, not trenched in afterward.</p><p><strong>Certification as the endpoint.</strong> Integration ends at legal-for-trade: the completed installation is tested and certified to NTEP standards and placed in service under the state weights-and-measures program, and it stays accurate only if the foundations and approaches the certification stands on were built to hold it. That is why the integration scope belongs in the engineering set from the start — the facility our <a href="/answers/grain-elevator-design/">grain elevator design</a> answer covers is metered, ticketed, and settled through this scale.</p></div></div></section>`,
  "grain-elevator-design": `<section class="block"><div class="container"><h2>The weigh scale: the elevator's <em>metering point</em></h2><div class="prose"><p>Every bushel this facility receives or ships crosses one instrument: the truck scale at its gate. Inbound loads are probed, weighed, dumped, and weighed out; outbound loads are settled on the same platform — which makes the scale's foundations, approaches, and traffic layout part of the elevator's structure, and its indicator and ticketing system part of the facility's books. How that scale is selected, founded, and tied into the receiving line and the scale house is worked through in our answer on <a href="/answers/grain-weigh-scale-design/">grain weigh scale design</a>.</p></div></div></section>`,
  "grain-terminal-design": `<section class="block"><div class="container"><h2>Weighing at the terminal: <em>trucks in, rail out</em></h2><div class="prose"><p>A surge terminal lives on throughput accounting: every truck that dumps and every railcar that loads has to be weighed accurately enough to settle against, at the pace the surge demands. That is the same discipline as truck scale integration for grain elevators — platform and rail scales founded to hold calibration, lanes sequenced probe, weigh, dump, and ticketing data feeding inventory — scaled to terminal volumes and worked through in our answer on <a href="/answers/grain-weigh-scale-design/">grain weigh scale design for truck and rail</a>.</p></div></div></section>`,
  "marine-cargo-terminal-design": `<section class="block"><div class="container"><h2>Marine terminal fabrication: <em>the steel between the drawings and the berth</em></h2><div class="prose"><p>Design decides what a terminal is; marine terminal fabrication decides whether it gets built as drawn. The fabricated scope of a cargo terminal is the engineered steel the operation runs on: ship-loader and conveyor-gallery structures, transfer towers, berth and mooring hardware, catwalks and access platforms, and the pipe and utility racks that cross the wharf. Each assembly is fabricated in the shop from the sealed design drawings, and the shop drawings that translate those designs into cut lengths, welds, and bolted connections are reviewed as part of the engineering scope — an error caught at the shop-drawing stage costs hours; the same error caught at erection costs weeks.</p><p><strong>Fit and tolerance.</strong> Marine structures are erected over water, often against existing wharf and dolphin structures that have settled, shifted, or corroded since they were surveyed. Fabrication tolerances are set for that reality: field-verified dimensions before steel is cut, slotted and adjustable connections where the existing structure cannot be trusted to the drawing, and splice points located where a crane on a barge can actually make the lift.</p><p><strong>Materials and protection.</strong> Terminal steel lives in the splash zone and the marine atmosphere, the most corrosive environment in structural practice. Fabrication specification covers steel grade and toughness for the service temperature, welding to AWS D1.1 with procedures qualified for the joint types the design uses, and coating systems — surface preparation, galvanizing or metallizing where specified, and multi-coat marine paint systems — applied in the shop where they can be inspected, not over water where they cannot.</p><p><strong>Modules and delivery.</strong> Where the berth allows it, assemblies are fabricated as modules — gallery sections, tower frames, platform units — trial-fitted in the shop and delivered by barge for a short erection window inside terminal operations. That sequencing is an engineering decision made with the fabricator, and it is why the fabrication scope belongs in the design set from the start rather than after it.</p></div></div></section>`,
  "port-arthur-marine-terminal-design": `<section class="block"><div class="container"><h2>Fabrication at the berth: <em>where this terminal gets built</em></h2><div class="prose"><p>A terminal design at Port Arthur is only as buildable as its fabricated steel: the loader and gallery structures, berth hardware, and access steel are shop-fabricated from the sealed drawings and erected over water against existing structures. How that scope is specified — tolerances for field-verified fit, AWS D1.1 welding, and coating systems for the splash zone — is worked through in our answer on <a href="/answers/marine-cargo-terminal-design/">marine terminal fabrication</a>.</p></div></div></section>`,
  "marine-berth-structural-design": `<section class="block"><div class="container"><h2>From berth design to <em>fabricated steel</em></h2><div class="prose"><p>Every load this page works through — berthing energy, mooring forces, deck and pile reactions — lands in fabricated steel: fender panels and their support frames, mooring hardware assemblies, and the catwalks and platforms crews work from. The fabrication standard behind those assemblies, from shop-drawing review to marine coating systems, is set out in our answer on <a href="/answers/marine-cargo-terminal-design/">marine terminal fabrication</a>.</p></div></div></section>`,
"broadcast-tower-engineering": `<section class="block"><div class="container"><h2>Broadcast towers and <em>TV towers</em>: one discipline, two names</h2><div class="prose"><p>Broadcast tower engineering and TV tower engineering are the same discipline read from two directions: the broadcast name describes the service the structure carries, and the TV name describes the antenna at its top. TV tower engineering starts from the load case that separates it from every other tower class — a high-power television antenna with its radome, feed lines, and mounting steel, an order of magnitude heavier than a cellular panel array, cantilevered at the very top of a mast that may run 1,000 to 1,500 feet, where every pound carries maximum leverage. The structural standard behind that work is TIA-222 at the higher structural classes broadcast service demands, with candelabra top configurations, rigid or semi-flexible waveguide runs, FAA obstruction lighting and marking, and RF safety coordination for the high-power environment designed in from the first calculation.</p><p>What TV tower engineering adds to the generic tower brief is the broadcaster's operating reality: the station cannot go dark for a structural project, so antenna replacements, reinforcement, and mount modifications are engineered around live operation — interim antennas, phased changeouts, and rigging sequences that keep the signal on air. The guyed mast and the self-supporting tower answer that brief differently, and choosing between them is a TV tower engineering decision made from the site, the height, and the antenna load — not from habit. That full scope, from foundation and guy anchors to the candelabra steel at the top, is the work this page documents.</p></div></div></section>`,
  "self-storage-facility-engineering": `<section class="block"><div class="container"><h2>The disciplines behind a <em>storage facility</em>, scope by scope</h2><div class="prose"><p>Self storage engineering is the coordination of three disciplines around one simple product: durable, leasable units on a site that drains, permits, and operates cleanly. The structural half designs the single-story drive-up and multi-story climate-controlled buildings — slabs designed as working surfaces for the vehicles, moving trucks, and pallet traffic that cross them daily, fire separations between units, and frames sized for the real storage loads plus the dynamic loads of dollies and carts. The civil engineer for self storage work carries the other half of the site: grading and stormwater that keep drive aisles dry, circulation geometry the trucks tenants actually bring can navigate, and utility coordination sequenced with the building pad. A civil engineer for self storage projects is judged on exactly that fit — a beautiful building on a site that floods or turns badly is a failed facility.</p><p>The self storage engineer holds the two halves together: the MEP and envelope design that keeps climate-controlled interiors at temperature, the egress and accessibility a multi-story building requires, and storage facility engineering design that treats the office and retail front, the gate and access systems, and the unit buildings as one permitted set. Read whole, storage facility engineering design is why two facilities with identical unit counts perform differently for thirty years — one was engineered as a system, the other was assembled from parts. The self storage engineer Apex Grid assigns scopes that system end to end, from the first site sketch to the sealed construction set.</p></div></div></section>`,
  "facade-retention-engineering": `<section class="block"><div class="container"><h2>The <em>façade</em> spelling, the retention system, and the permanent condition</h2><div class="prose"><p>The discipline travels under two spellings — facade retention engineering in American practice, façade retention engineering in the British and Commonwealth literature where the technique matured — and one system: the temporary steel frame that holds a historic street wall while everything behind it is demolished and rebuilt. Façade retention engineering and its American-spelled twin describe the same scope this page works through: analysis of the wall as it actually stands, a retention frame designed for its geometry, height, and exposure, monitoring through the construction zone, and a defined permanent condition at the end. A project team searching either spelling is asking for the same engineer.</p><p>The facade retention system design is where that scope becomes steel. A facade retention system design starts from the survey — the wall's materials, its existing ties and failures, the party walls it shares — and sizes the frame for wind on a wall that no longer has a building behind it, for the demolition sequence that will load it unevenly, and for the new structure that must eventually take the wall back. The best facade retention system design is the one nobody notices: the frame reads as scaffolding from the street, the monitoring catches movement in millimeters, and the wall comes through the project in the condition the preservation approval promised.</p></div></div></section>`,
"synagogue-structural-design": `<section class="block"><div class="container"><h2>The <em>Engineer</em> Synagogue Committees Actually Hire</h2><div class="prose"><p>When a congregation builds, the brief arrives in a specific order: the sanctuary's clear span and sightlines to the bimah and ark first; then the separation problem — a social hall in full use while a service runs next door; then the kosher kitchen, which is really two kitchens with separate MEP zones for meat and dairy; and the security posture the congregation has chosen, carried through site standoff, controlled entries, and glazing. Apex Grid works as an engineer synagogue congregations can scope against that whole brief at once, because the structure is what each part hangs from: spans set the frame, wall mass and floor assemblies set the acoustics, floor loading carries the kitchen equipment, and the envelope carries the security design.</p><p>That is the standard an engineer synagogue projects — new builds, additions, and renovations alike — are judged by: the existing frame, read honestly, decides what a new span, a larger hall, or an enlarged kitchen can ask of it, and the durable answer is the one the community is still using a generation later. The discipline-by-discipline picture — long-span sanctuary roofs, bell towers and steeples, seating balconies, and historic renovation — is set out on our page for a <a href="/industries/religious-worship/structural-engineering/">structural engineer for churches</a> and worship facilities generally, which documents the worship-sector structural scope this answer draws on.</p></div></div></section>`,
  "chapel-design": `<section class="block"><div class="container"><h2>The chapel's closest cousin: the <em>synagogue</em></h2><div class="prose"><p>A chapel and a synagogue share the worship-space fundamentals — clear spans, sightlines, acoustics tuned for speech and chant — and diverge on program: the synagogue adds a social hall in simultaneous use, classrooms, and a kosher kitchen engineered as two kitchens. How that fuller brief is structured, from acoustic separation to the security-driven envelope, is worked through in our answer on <a href="/answers/synagogue-structural-design/">synagogue structural design</a>.</p><p>The professional behind that structure is the chapel engineer: the licensed engineer who reads a small worship space as one system — the clear span the sightlines demand, the structure-borne silence the acoustics depend on, and the MEP that has to disappear into both. A chapel engineer scopes the sanctuary's frame and its services together, because in a room built for chant and spoken word, a duct rumble or a visible diffuser is a design failure, not a detail. That is the standard a chapel engineer is hired to hold: structure, silence, and services reconciled in one sealed set before the first service is ever scheduled.</p></div></div></section>`,
  "church-design": `<section class="block"><div class="container"><h2>The synagogue case: <em>same structure, harder program</em></h2><div class="prose"><p>Church design and synagogue design start from the same sanctuary engineering — spans, sightlines, assembly loads — but the synagogue's program runs harder: simultaneous uses separated acoustically, a kosher kitchen doubled into meat and dairy zones, and security designed into the site and envelope. Our answer on <a href="/answers/synagogue-structural-design/">synagogue structural design</a> works through that case in full, and it is the closest reference for any worship building whose program mixes worship, education, and social functions under one roof.</p></div></div></section>`,
  "high-altitude-observatory-hvac-design": `<section class="block"><div class="container"><h2><em>HVAC Observatory</em> Design: Where the Checklist Comes From</h2><div class="prose"><p>Every item on the checklist above exists because a high-altitude project failed without it, usually in the first winter. Observatory HVAC design inverts the commercial order of operations: instead of sizing equipment from a catalog and checking the site afterward, the engineer starts from the summit — actual air density at elevation, the manufacturer's published derating tables, and a design day set by survival rather than comfort — and only then selects equipment. Fans are chosen for the mass flow the building needs at thin-air density, combustion plant is derated and still required to meet the load with margin, and refrigerant systems are charged and relieved for the site's atmospheric pressure. On an HVAC observatory project, the observatory HVAC engineer's first document is the derating table, not the last check.</p><p>The second inversion is operational. An observatory HVAC system is designed to fail toward safety: heat stays on through sensor or power failure, hydronic loops exposed to risk carry antifreeze, low-temperature alarms report remotely, and the winterization manual is an engineering deliverable, not an afterthought. That is what HVAC observatory work finally is — ordinary building services engineered for a building that cannot be allowed to freeze, on a site where a service call can wait out a blizzard.</p></div></div></section>`,
  "church-hvac-design": `<section class="block"><div class="container"><h2>When the worship space sits at <em>altitude</em></h2><div class="prose"><p>Some church HVAC projects leave the standard playbook entirely: a mountain congregation or retreat facility at elevation, where thin air derates every furnace and fan and a heating failure in a blizzard is a building-survival event, not a comfort complaint. That design case — altitude derating, density-corrected ventilation, and freeze-proof redundancy — is worked through in our answer on <a href="/answers/high-altitude-observatory-hvac-design/">high-altitude observatory HVAC design</a>, which covers the altitude discipline system by system.</p></div></div></section>`,
  "demand-response-hvac-design": `<section class="block"><div class="container"><h2>The other end of the HVAC design envelope: <em>altitude</em></h2><div class="prose"><p>Demand response is about shedding load on the grid's worst day; altitude design is about equipment that cannot shed anything on the building's worst night. The two meet in controls that fail toward safety. How HVAC is engineered where air density, derating, and freeze survival govern every selection is covered in our answer on <a href="/answers/high-altitude-observatory-hvac-design/">HVAC design for high-altitude observatory buildings</a>.</p></div></div></section>`,
};

function phase0AeoPage(page: Phase0AeoPage | Phase7AeoSeed): string {
  const phase7 = "cluster" in page;
  const related = phase7
    ? PHASE7_AEO_PAGES
      .filter((candidate) => candidate.slug !== page.slug && candidate.cluster === page.cluster)
      .slice(0, 3)
      .map((candidate) => ({ label: candidate.h1, href: `/answers/${candidate.slug}/` }))
    : PHASE0_AEO_PAGES
      .filter((candidate) => candidate.slug !== page.slug).slice(0, 3)
      .map((candidate) => ({ label: candidate.h1, href: `/answers/${candidate.slug}/` }));
  const serviceHref = "cluster" in page ? page.serviceHref : (page.serviceHref ?? "/services/");
  // /estimate retired 2026-10-26 (Jeremy: estimates are given personally) —
  // corpus extraLinks that still point at it render as the contact intake.
  const links = [
    ...related,
    ...("cluster" in page && page.cluster === "Cost and pricing"
      ? [{ label: "Request a project review", href: "/contact" }]
      : []),
    ...("cluster" in page ? [] : (page.extraLinks ?? []).map((link) => (link.href === "/estimate" || link.href === "/estimate/" ? { label: "Request a project review", href: "/contact" } : link))),
    { label: "Engineering service for this question", href: serviceHref },
    { label: "Metro engineering guides", href: "/metros/" },
    { label: "Verified service areas", href: "/locations/" },
  ];
  const faqs = substantiveFaqs("cluster" in page ? phase7Faqs(page) : page.faqs);
  const customSections = "cluster" in page ? undefined : page.sections;
  // The hero renders page.answer verbatim (as the lede, or as the direct
  // answer when the two are identical), so the default first section must
  // not repeat it word for word.
  const heroText = "cluster" in page ? page.answer : (page.directAnswer ?? page.answer);
  const sections = !customSections?.length
    ? [
      ...(heroText === page.answer ? [] : [{ heading: "The concise answer", body: page.answer }]),
      { heading: "How the answer is applied", body: `The correct application of ${page.topic.toLowerCase()} starts with the actual project, not a generic promise. Confirm the jurisdiction, adopted code, design scope, existing conditions, required deliverables, and professional responsibility before relying on a conclusion. A responsible engineer documents assumptions and identifies information that still needs verification.` },
      { heading: "What can change the result", body: "Project type, occupancy, existing construction, site conditions, code edition, agency requirements, and changes made after the original design can change the work. A concise answer is useful for orientation, but the signed or sealed project record must reflect the current scope and the authority's process.", bullets: ["Confirm the authority having jurisdiction and current checklist", "Use current drawings, calculations, field evidence, and equipment information", "Separate engineering decisions from owner, architect, contractor, utility, and agency decisions", "Record assumptions, limitations, and questions requiring direct AHJ confirmation"] },
    ]
    : customSections;
  return phase0ArticleFrame({
    canonical: `/answers/${page.slug}/`,
    title: page.title,
    description: page.description,
    h1: page.h1,
    kicker: `AEO Answer · ${page.topic}`,
    answer: page.answer,
    sections,
    faqs,
    links,
    schemaType: "Article",
    author: PHASE0_JEREMY_AUTHOR,
    founderNote: "cluster" in page ? undefined : page.founderNote,
    marker: "cluster" in page ? "phase7" : undefined,
    directAnswer: "cluster" in page ? undefined : page.directAnswer,
    suppressEmptyFaq: true,
    facts: "cluster" in page ? undefined : page.facts,
    howTo: "cluster" in page ? undefined : page.howTo,
    visual: motifForText(`${"cluster" in page ? page.cluster : page.topic} ${page.h1}`),
    extraBodyHtml: ANSWER_EXTRA_SECTIONS[page.slug],
  });
}

