type LibraryIndexEntry = { slug: string; name: string; blurb: string; href: string };

function libraryDerivedName(page: Phase0AeoPage): string {
  const topic = (page.topic ?? "").trim();
  if (topic && !/\?$/.test(topic)) return topic;
  return page.title.replace(/\s*\|\s*Apex Grid.*$/i, "").replace(/\?\s*$/, "").trim();
}

function libraryDerivedBlurb(page: Phase0AeoPage): string {
  const raw = (page.directAnswer ?? page.description ?? "").replace(/\s+/g, " ").trim();
  if (raw.length <= 140) return raw;
  const cut = raw.slice(0, 140);
  const lastSpace = cut.lastIndexOf(" ");
  return `${(lastSpace > 60 ? cut.slice(0, lastSpace) : cut).replace(/[\s,;:—-]+$/, "")}…`;
}

// GROWTH RULE (program law): the A–Z index is built from the corpus arrays
// themselves. Future deepened pages join the Library by being added to
// WAVE_LIBRARY_ANSWER_PAGES — any record added there appears in this index
// automatically in the same deploy, with no further hub edit. Seed records
// come from the Phase 0 batch arrays; the featured batch-1 slugs and the
// wave-ec cold-storage record are named explicitly. Dedupe is by slug and
// keeps the LAST occurrence in ALL_AEO_PAGES order, so a deepened record
// always wins over its starter tuple and no slug is ever listed twice.
function libraryIndexEntries(): LibraryIndexEntry[] {
  const included = new Set<string>();
  for (const page of PHASE0_BATCH1_AEO_PAGES) included.add(page.slug);
  for (const page of PHASE0_BATCH2_AEO_PAGES) included.add(page.slug);
  for (const page of PHASE0_BATCH3_PROJECT_PAGES) included.add(page.slug);
  for (const slug of LIBRARY_FEATURED_SLUGS) included.add(slug);
  for (const page of WAVE_LIBRARY_ANSWER_PAGES) included.add(page.slug);
  included.add("cold-storage-design");
  const bySlug = new Map<string, Phase0AeoPage>();
  for (const page of ALL_AEO_PAGES) {
    if (!included.has(page.slug)) continue;
    if ("cluster" in page) continue;
    bySlug.set(page.slug, page as Phase0AeoPage);
  }
  const missing = [...included].filter((slug) => !bySlug.has(slug));
  if (missing.length) {
    throw new Error(`SEO assertion failed: Apex Engineering Library index is missing corpus records: ${missing.join(", ")}`);
  }
  const entries = [...bySlug.values()].map((page) => {
    const override = LIBRARY_DISPLAY_OVERRIDES[page.slug];
    return {
      slug: page.slug,
      name: override?.name ?? libraryDerivedName(page),
      blurb: override?.blurb ?? libraryDerivedBlurb(page),
      href: `/answers/${page.slug}/`,
    };
  });
  entries.sort((a, b) => a.name.localeCompare(b.name));
  return entries;
}

function libraryIndexLinks(): Array<{ label: string; href: string }> {
  return libraryIndexEntries().map((entry) => ({ label: entry.name, href: entry.href }));
}

type LibraryCatalogEntry = { slug: string; name: string; href: string };

// COMPLETENESS TIER — the curated A–Z index above is the Library's front
// door, but it must never be the only path into the corpus: the internal-link
// audit (writeNormalizedInternalLinkReport) fails the build when an indexable
// sitemap page has zero contextual inbound links, and most answer pages are
// reached only through this hub. The catalog tier therefore lists EVERY
// answer record in ALL_AEO_PAGES exactly once. Dedupe is by slug and keeps
// the LAST occurrence in ALL_AEO_PAGES order, so a deepened record always
// wins over its starter tuple — the same rule the curated index uses.
// Labels are the display override when one exists, else the record's h1.
function libraryCatalogEntries(): LibraryCatalogEntry[] {
  const bySlug = new Map<string, Phase0AeoPage | Phase7AeoSeed>();
  for (const page of ALL_AEO_PAGES) bySlug.set(page.slug, page);
  const entries = [...bySlug.values()].map((page) => {
    const override = LIBRARY_DISPLAY_OVERRIDES[page.slug];
    const name = (override?.name ?? page.h1).trim() || page.slug;
    return { slug: page.slug, name, href: `/answers/${page.slug}/` };
  });
  entries.sort((a, b) => a.name.localeCompare(b.name) || a.slug.localeCompare(b.slug));
  return entries;
}

function libraryHubBodyHtml(): string {
  const entries = libraryIndexEntries();
  const byLetter = new Map<string, LibraryIndexEntry[]>();
  for (const entry of entries) {
    const letter = (entry.name.charAt(0) || "#").toUpperCase();
    const list = byLetter.get(letter) ?? [];
    list.push(entry);
    byLetter.set(letter, list);
  }
  const letters = [...byLetter.keys()].sort();
  const topic = `<section class="block"><div class="container"><h2>Topic of the Week</h2><div class="prose"><p><strong><a href="${esc(LIBRARY_TOPIC_OF_THE_WEEK.href)}">${esc(LIBRARY_TOPIC_OF_THE_WEEK.name)}</a></strong></p><p>${esc(LIBRARY_TOPIC_OF_THE_WEEK.body)}</p><p><a href="${esc(LIBRARY_TOPIC_OF_THE_WEEK.href)}">Read the full Title 24 reference entry</a></p></div></div></section>`;
  const news = `<section class="block"><div class="container"><h2>What's Big in Engineering Today</h2><div class="prose">${LIBRARY_NEWS_ITEMS.map((item) => `<p><strong>${esc(item.date)} — ${esc(item.headline)}</strong><br>${esc(item.summary)}<br>Source: <a href="${esc(item.sourceUrl)}" rel="noopener noreferrer">${esc(item.sourceLabel)}</a>${item.related ? `<br>Related Library topic: <a href="/answers/${esc(item.related.slug)}/">${esc(item.related.label)}</a>` : ""}</p>`).join("")}<p>News updated ${esc(LIBRARY_NEWS_UPDATED)}.</p></div></div></section>`;
  const index = `<section class="block"><div class="container"><h2>Browse the Library A–Z</h2><div class="prose"><p>Every reference entry in the Apex Engineering Library, in alphabetical order. Each entry answers one engineering question in plain language, with the records, code basis, and professional boundaries a real project needs.</p></div>${letters.map((letter) => `<h3>${esc(letter)}</h3><div class="linkrow">${(byLetter.get(letter) ?? []).map((entry) => `<a href="${esc(entry.href)}">${esc(entry.name)}</a>`).join("")}</div>${(byLetter.get(letter) ?? []).map((entry) => `<p><strong><a href="${esc(entry.href)}">${esc(entry.name)}</a></strong> — ${esc(entry.blurb)}</p>`).join("")}`).join("")}</div></section>`;
  const catalogEntries = libraryCatalogEntries();
  const catalogByLetter = new Map<string, LibraryCatalogEntry[]>();
  for (const entry of catalogEntries) {
    const letter = (entry.name.charAt(0) || "#").toUpperCase();
    const list = catalogByLetter.get(letter) ?? [];
    list.push(entry);
    catalogByLetter.set(letter, list);
  }
  const catalogLetters = [...catalogByLetter.keys()].sort();
  const catalog = `<section class="block"><div class="container"><h2>Browse the Full Library — Complete Catalog</h2><div class="prose"><p>The complete catalog of the Apex Engineering Library: every reference entry, in alphabetical order. Each link opens one entry answering one engineering question in plain language, with the records, code basis, and professional boundaries a real project needs.</p></div>${catalogLetters.map((letter) => `<h3>${esc(letter)}</h3><div class="linkrow">${(catalogByLetter.get(letter) ?? []).map((entry) => `<a href="${esc(entry.href)}">${esc(entry.name)}</a>`).join("")}</div>`).join("")}</div></section>`;
  return `${topic}\n  ${news}\n  ${index}\n  ${catalog}`;
}

function phase0CollectionHub(
  canonical: string,
  title: string,
  description: string,
  h1: string,
  kicker: string,
  answer: string,
  links: Array<{ label: string; href: string }>,
  extraBodyHtml?: string,
): string {
  return phase0ArticleFrame({
    canonical,
    title,
    description,
    h1,
    kicker,
    answer,
    sections: [
      { heading: "How to use this collection", body: "These pages are national, general guidance. They explain useful questions and records without inventing local permit outcomes, county requirements, client records, or project pricing. Confirm the current jurisdiction, code edition, authority checklist, and responsible professional before relying on a page for a live project." },
      { heading: "A consistent professional boundary", body: "Apex Grid's public guidance does not replace a project proposal, site investigation, design analysis, permit review, inspection, or board decision. Scope, licensing, responsible charge, and deliverables are confirmed for each project." },
    ],
    faqs: [
      { question: "Are these pages static and indexable?", answer: "Yes. Phase 0 pages are generated as static HTML with a self-canonical URL and index,follow metadata, then included in the generated sitemap." },
      { question: "Do these pages contain local guarantees or pricing?", answer: "No. The corpus intentionally excludes invented local records, near-me doorway pages, county guides, and inline location pricing." },
    ],
    links,
    schemaType: "WebPage",
    extraBodyHtml,
  });
}

function phase1MetroFaqs(metro: Phase1Metro, serviceLabel?: string): Array<{ question: string; answer: string }> {
  const subject = serviceLabel
    ? `${serviceLabel} for the ${metro.metroName} metro`
    : `engineering guides for the ${metro.metroName} metro`;
  return [
    {
      question: `What does ${subject} cover?`,
      answer: `This guide explains planning, records, coordination, and professional boundaries for ${subject}. The exact project scope, responsible professional, and deliverables are confirmed from current records.`,
    },
    {
      question: "Do these metro pages guarantee permit approval?",
      answer: "No. The authority having jurisdiction controls its checklist, interpretation, inspections, review, and approval. A general metro guide cannot promise a local outcome.",
    },
    {
      question: "What should I send for a metro engineering review?",
      answer: "Send the project address, scope, current drawings, existing-condition evidence, equipment or utility information, prior comments, applicable authority information, and requested deliverables. The responsible professional identifies what else is needed.",
    },
  ];
}

