function blogPostPage(post: BlogPost): string {
  const crumbs = [
    { name: "Home", href: "/" },
    { name: "Blog", href: "/blog/" },
    { name: post.title },
  ];
  const dateStr = new Date(post.date + "T12:00:00Z").toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });
  const articleAuthor = post.author
    ? { "@type": "Person", "@id": post.author.personId, name: post.author.name, url: post.author.profileUrl }
    : { "@type": "Organization", name: "Apex Grid Engineering", url: SITE };
  const articleSchema = {
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    headline: post.title,
    description: post.description,
    datePublished: post.date,
    dateModified: post.date,
    articleSection: post.tag,
    author: articleAuthor,
    publisher: { "@type": "Organization", "@id": `${SITE}/#business`, name: "Apex Grid Engineering", url: SITE },
    mainEntityOfPage: `${SITE}/blog/${post.slug}/`,
  };
  const faqSchema = post.faqs?.length
    ? {
        "@context": "https://schema.org",
        "@type": "FAQPage",
        mainEntity: post.faqs.map((faq) => ({
          "@type": "Question",
          name: faq.q,
          acceptedAnswer: { "@type": "Answer", text: faq.a },
        })),
      }
    : null;
  const others = BLOG_POSTS
    .filter((p) => p.slug !== post.slug)
    .sort((a, b) => Number(b.tag === post.tag) - Number(a.tag === post.tag))
    .slice(0, 3);
  const body = `
${breadcrumb(crumbs)}
<section class="hero"><div class="container">
  <p class="kicker">${esc(post.tag)} · ${esc(dateStr)} · ${post.minutes} min read</p>
  <h1>${esc(post.title)}</h1>
  <p class="lede">${esc(post.description)}</p>${post.author ? `
  <p>By <a href="${esc(post.author.profileUrl)}" rel="author">${esc(post.author.name)}</a> · ${esc(post.author.role)}</p>` : ""}${post.editorialApproval ? `
  <p class="note">${esc(post.editorialApproval.label)}</p>` : ""}
</div></section>
<section class="block"><div class="container"><div class="prose">${post.html}</div></div></section>
${post.author ? `<section class="block"><div class="container container--narrow">
  <h2>About the Author</h2>
  <p><a href="${esc(post.author.profileUrl)}" rel="author"><strong>${esc(post.author.name)}</strong></a> is ${esc(post.author.role)}. Read his verified founder profile and other expert answers.</p>
</div></section>` : ""}
${southAfricaBlogSupportSection(post)}
${post.faqs?.length ? `<section class="block"><div class="container faq">
  <h2>Quick <em>Answers</em></h2>
  ${post.faqs.map((faq) => `<details><summary>${esc(faq.q)}</summary><div class="a">${esc(faq.a)}</div></details>`).join("")}
</div></section>` : ""}
<section class="block"><div class="container">
  <h2>More from the <em>Blog</em></h2>
  <div class="grid3">
  ${others
    .map((p) => `<a class="card" href="/blog/${p.slug}/"><div class="label">${esc(p.tag)}</div><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p></a>`)
    .join("")}
  </div>
</div></section>
<section class="ctaband"><div class="container">
  <h2>Have a Project in Mind?</h2>
  <p>${post.tag === "South Africa"
    ? "Planning a South Africa opportunity? We can help define the cross-border brief and identify the local registrations and partnerships that must be verified."
    : `${LICENSING_COVERAGE_STATEMENT} ${PROJECT_JURISDICTION_NOTE}`}</p>
  <a class="cta" href="/contact">Request a Proposal</a>
</div></section>`;
  return htmlShell({
    title: `${post.title} | Apex Grid Engineering Blog`,
    description: post.description,
    canonical: `${SITE}/blog/${post.slug}/`,
    schemaJson: [orgSchema, articleSchema, ...(faqSchema ? [faqSchema] : []), breadcrumbSchema(crumbs)],
    body,
  });
}

/** Hardening Wave 2 (2026-11-06): South Africa blog carrier — HIGH S1
 *  for the long-tail "south africa building energy compliance glazing
 *  shading standards" (x0, 737w, anchors 0). The phrase is a query
 *  concatenation of the post's own published topics; the honest cure
 *  carries every element in one grounded passage rather than faking
 *  the string: the post's own record (National Building Regulations,
 *  SANS 10400-XA, envelope/glazing/HVAC/lighting/controls/hot water,
 *  Johannesburg/Cape Town/Durban climate spread, locally registered
 *  professionals). Gated on the post slug inside blogPostPage. */
function southAfricaBlogSupportSection(post: BlogPost): string {
  if (post.slug !== "south-africa-commercial-building-energy-efficiency") return "";
  return `<section class="block"><div class="container"><div class="prose"><h2>South Africa Building Energy Compliance: Glazing, Shading, and the Standards Behind Them</h2><p>South Africa building energy compliance turns on how a facade handles sun, and the glazing and shading decisions are where the standard is won or lost. Under the National Building Regulations and SANS 10400-XA, the energy-use provisions referenced for commercial buildings, the envelope is assessed as part of a whole-building approach that connects glazing performance, external shading, mechanical systems, lighting, controls, and hot water — so a specification that treats the glass as an architectural finish and the shading as an afterthought fails the compliance logic even when each product performs on paper. The standards expect the fenestration to be designed with the climate file: Johannesburg's highveld sun, Cape Town's winter rain and summer glare, and Durban's humid coast each push the glazing ratio, shading depth, and solar control in different directions.</p><p>That is why the compliance record for a South African commercial building is built the way this article sets out — envelope first, systems reconciled against it, and the submission confirmed against the current local expectations with the locally registered professionals responsible for South African compliance. Glazing and shading are not the decorative end of that record; they are its first calculation.</p></div></div></section>`;
}

